/**
 * Join ordering of the LMDB pipeline when the sketch-based estimator is not ready: plans must be connected and the cost
 * of a pattern must not be discounted for a bound variable that no available index can seek on.
 */
class LmdbIndexAwareJoinOptimizerTest {

	private static final String EX = "http://example.org/";

	/**
	 * F binds {@code ?b}. Pattern O ({@code ?x ?y ?b}) can only use {@code ?b} as a bound object, pattern S
	 * ({@code ?b ex:pS ?z}) can seek on it as a subject.
	 */
	private static final String INDEX_QUERY = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT * WHERE { ?a ex:pF ?b . ?x ?y ?b . ?b ex:pS ?z . }";
	private static final String MIXED_BINDING_QUERY = "PREFIX ex: <" + EX + ">\n"
			+ "SELECT * WHERE { ?a ex:pF ?s . ?s ?p <urn:o> . }";

	@TempDir
	File dataDir;

	@Test
	void connectedPatternIsPickedBeforeCheaperDisconnectedPattern() throws IOException {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { ?a ex:pA ?b . ?b ex:pB ?c . ?c ex:pD ?d . }", "spoc,posc,ospc");

		assertThat(predicates(plan)).containsExactly(EX + "pA", EX + "pB", EX + "pD");
	}

	@Test
	void boundObjectWithoutObjectIndexDoesNotMakePatternLookCheap() throws IOException {
		TupleExpr plan = optimize(INDEX_QUERY, "spoc,posc");

		assertThat(predicates(plan))
				.as("S can seek on the bound subject; O cannot seek on its bound object without an object index")
				.containsExactly(EX + "pF", EX + "pS", null);
	}

	@Test
	void boundObjectWithObjectIndexKeepsItsDiscount() throws IOException {
		TupleExpr plan = optimize(INDEX_QUERY, "spoc,posc,ospc");

		assertThat(predicates(plan)).as("with an ospc index O seeks on its bound object and stays cheapest")
				.containsExactly(EX + "pF", null, EX + "pS");
	}

	@Test
	void indexAwareOrderingAlsoAppliesWhenTheQueryContainsValues() throws IOException {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { VALUES ?a { ex:v1 } ?a ex:pF ?b . ?x ?y ?b . ?b ex:pS ?z . }", "spoc,posc");

		assertThat(predicates(plan)).containsExactly(EX + "pF", EX + "pS", null);
	}

	@Test
	void recordedCostIsTheDiscountFreeCostWhenTheBoundObjectCanBeSeeked() throws IOException {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { ?a ex:pF ?b . ?x ?y ?b . }", "spoc,posc,ospc");

		// (cardinality 100 + 5) ^ (2 unbound / 3 non-constant variables)
		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(Math.pow(105, 2.0 / 3.0), within(0.01));
	}

	@Test
	void recordedCostUndoesTheDiscountWhenTheBoundObjectCannotBeSeeked() throws IOException {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { ?a ex:pF ?b . ?x ?y ?b . }", "spoc,posc");

		// the bound object cannot be seeked on, so the base discount is undone: (105 ^ (2/3)) * 105 ^ (1/3)
		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(105.0, within(0.01));
	}

	@Test
	void boundSubjectKeepsItsDiscountWithAResidualObjectConstant() throws IOException {
		TupleExpr plan = optimize(MIXED_BINDING_QUERY, "spoc,posc");

		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(Math.sqrt(105.0), within(0.01));
	}

	@ParameterizedTest
	@CsvSource({ "'spoc,opsc', 0.5", "'opsc,spoc', 1.0" })
	void equalLengthPrefixesUseTheSameIndexAsTheScan(String indexes, double exponent) throws IOException {
		TupleExpr plan = optimize(MIXED_BINDING_QUERY, indexes);

		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(Math.pow(105, exponent), within(0.01));
	}

	@ParameterizedTest
	@CsvSource({ "'spoc,posc', 2", "'cspo,posc', 1" })
	void boundContextIsDiscountedWhenItsComponentIsInThePrefix(String indexes, int exponentNumerator)
			throws IOException {
		ValueFactory vf = SimpleValueFactory.getInstance();
		StatementPattern source = new StatementPattern(Var.of("g"), Var.of("pF", vf.createIRI(EX, "pF")),
				Var.of("s"));
		StatementPattern target = new StatementPattern(Scope.NAMED_CONTEXTS, Var.of("s"), Var.of("p"),
				Var.of("o", vf.createIRI("urn:o")), Var.of("g"));
		TupleExpr plan = optimize(new QueryRoot(new Join(source, target)), indexes);

		assertThat(pattern(plan, null).getCostEstimate())
				.isCloseTo(Math.pow(105, exponentNumerator / 3.0), within(0.01));
	}

	@Test
	void boundSubjectKeepsItsDiscountWithinAGraphScope() throws IOException {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { GRAPH ?g { ?a ex:pF ?s . ?s ?p <urn:o> . } }", "spoc,posc");

		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(Math.sqrt(105.0), within(0.01));
	}

	@Test
	void boundNameKeepsItsDiscountWhenAnyOccurrenceIsInThePrefix() throws IOException {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { ?a ex:pF ?s . ?s ?p ?s . }", "spoc,posc");

		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(Math.pow(105, 1.0 / 3.0), within(0.01));
	}

	@Test
	void repeatedBoundNameOutsideThePrefixIsCountedOnce() throws IOException {
		TupleExpr plan = optimize("PREFIX ex: <" + EX + ">\n"
				+ "SELECT * WHERE { ?a ex:pF ?s . ?p ?s ?s . }", "spoc");

		assertThat(pattern(plan, null).getCostEstimate()).isCloseTo(Math.pow(105, 2.0 / 3.0), within(0.01));
	}

	private TupleExpr optimize(String query, String indexes) throws IOException {
		// A standalone parse selects the legacy GRAPH translation; these plans are costed on the explicit Graph node.
		return optimize(QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null,
				QueryParseOptions.DEFAULT.withGraphAlgebraMode(GraphAlgebraMode.GRAPH)).getTupleExpr(), indexes);
	}

	private TupleExpr optimize(TupleExpr expr, String indexes) throws IOException {
		try (TripleStore tripleStore = new TripleStore(dataDir, new LmdbStoreConfig(indexes), null)) {
			LmdbStandardQueryOptimizerPipeline pipeline = pipeline(new FixedCardinalityStatistics(tripleStore));
			List<QueryOptimizer> optimizers = new ArrayList<>();
			pipeline.getOptimizers().forEach(optimizers::add);
			assertThat(optimizers.stream().map(o -> o.getClass().getSimpleName()))
					.contains("LmdbIndexAwareJoinOptimizer");

			for (QueryOptimizer optimizer : optimizers) {
				optimizer.optimize(expr, null, EmptyBindingSet.getInstance());
			}
			return expr;
		}
	}

	private static LmdbStandardQueryOptimizerPipeline pipeline(LmdbEvaluationStatistics statistics) {
		TripleSource tripleSource = new EmptyTripleSource();
		EvaluationStrategy strategy = new DefaultEvaluationStrategyFactory().createEvaluationStrategy((Dataset) null,
				tripleSource, statistics, QueryExecutionPolicy.EXPERIMENTAL);
		return new LmdbStandardQueryOptimizerPipeline(strategy, tripleSource, statistics);
	}

	/** Predicates of all statement patterns in plan order; {@code null} for a variable predicate. */
	private static List<String> predicates(TupleExpr plan) {
		List<String> predicates = new ArrayList<>();
		plan.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				predicates.add(node.getPredicateVar().hasValue() ? node.getPredicateVar().getValue().stringValue()
						: null);
			}
		});
		return predicates;
	}

	private static StatementPattern pattern(TupleExpr plan, String predicate) {
		List<StatementPattern> found = new ArrayList<>();
		plan.visit(new AbstractSimpleQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(StatementPattern node) {
				String p = node.getPredicateVar().hasValue() ? node.getPredicateVar().getValue().stringValue() : null;
				if ((predicate == null && p == null) || (predicate != null && predicate.equals(p))) {
					found.add(node);
				}
			}
		});
		assertThat(found).as(plan.toString()).hasSize(1);
		return found.get(0);
	}

	private static final class FixedCardinalityStatistics extends LmdbEvaluationStatistics {

		FixedCardinalityStatistics(TripleStore tripleStore) {
			super(mock(ValueStore.class), tripleStore, null);
		}

		@Override
		public double getCardinality(TupleExpr expr) {
			if (expr instanceof StatementPattern pattern) {
				if (!pattern.getPredicateVar().hasValue()) {
					return 100;
				}
				return switch (pattern.getPredicateVar().getValue().stringValue().substring(EX.length())) {
				case "pF", "pA" -> 2;
				case "pB" -> 1000;
				case "pD" -> 3;
				case "pS" -> 5000;
				default -> 10;
				};
			}
			return super.getCardinality(expr);
		}
	}

	private static final class EmptyTripleSource implements TripleSource {

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subj, IRI pred, Value obj,
				Resource... contexts) throws QueryEvaluationException {
			return EMPTY_ITERATION;
		}

		@Override
		public ValueFactory getValueFactory() {
			return SimpleValueFactory.getInstance();
		}
	}
}
